// Init Run — builds the run context and a typed config object from viral_config rows.
// Any missing key falls back to DEFAULTS, so deleting a row never breaks the run.

const DEFAULTS = {
  w_velocity: 0.30,
  w_outperformance: 0.20,
  w_acceleration: 0.20,
  w_engagement: 0.10,
  w_recency: 0.10,
  w_priority: 0.10,
  vph_log_floor: 3,
  vph_log_ceil: 6,
  engagement_cap: 0.08,
  recency_tau_h: 36,
  min_velocity_interval_h: 0.5,
  eligible_score_min: 60,
  eligible_score_min_lowconf: 80,
  eligible_max_age_h: 48,
  expire_age_h: 72,
  min_duration_s: 15,
  max_duration_s: 1800,
  watchlist_items_per_source: 10,
  charts_enabled: 1,
  charts_max_pages: 2,
  charts_excluded_categories: '1,10',
  allowed_languages: 'en,en-US,en-GB',
  snapshot_retention_days: 5,
  title_exclude_keywords: 'official music video,official video,lyric video,lyrics,official audio,visualizer,trailer,teaser',
  twitch_client_id: '',
  twitch_clip_window_h: 48,
  twitch_clips_per_source: 20,
  twitch_min_duration_s: 5,
  twitch_vph_log_floor: 1,
  twitch_vph_log_ceil: 3,
  twitch_eligible_max_age_h: 72,
  twitch_expire_age_h: 96,
  twitch_eligible_min_views: 250,
  eligible_keep_min: 50,
};

const LIST_KEYS = ['charts_excluded_categories', 'allowed_languages', 'title_exclude_keywords'];
const WEIGHT_KEYS = ['w_velocity', 'w_outperformance', 'w_acceleration', 'w_engagement', 'w_recency', 'w_priority'];

const warnings = [];
const config = { ...DEFAULTS };
const seen = new Set();

// 1. Read rows from viral_config
for (const item of $input.all()) {
  const r = item.json;
  const key = String(r.key ?? '').trim();
  if (!key) continue;
  if (seen.has(key)) warnings.push(`duplicate key "${key}": last row wins`);
  seen.add(key);

  const hasNum = r.value_number !== null && r.value_number !== undefined && Number.isFinite(Number(r.value_number));
  const hasStr = typeof r.value_string === 'string' && r.value_string.trim() !== '';

  if (typeof DEFAULTS[key] === 'number') {
    const v = hasNum ? Number(r.value_number) : (hasStr ? Number(r.value_string) : NaN);
    if (Number.isFinite(v)) config[key] = v;
    else warnings.push(`key "${key}" has no valid number: default ${DEFAULTS[key]} used`);
  } else if (hasStr) {
    config[key] = r.value_string.trim();
  } else if (hasNum) {
    config[key] = Number(r.value_number);
  } else {
    warnings.push(`key "${key}" is empty: default used`);
  }
}

for (const key of Object.keys(DEFAULTS)) {
  if (!seen.has(key)) warnings.push(`key "${key}" missing in viral_config: default used`);
}

// 2. Comma-separated strings -> arrays
for (const key of LIST_KEYS) {
  config[key] = String(config[key] ?? '')
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);
}
config.allowed_languages = config.allowed_languages.map(s => s.toLowerCase());
config.title_exclude_keywords = config.title_exclude_keywords.map(s => s.toLowerCase());

// 3. Weights must sum to 1 (normalize if they do not)
const weightSum = WEIGHT_KEYS.reduce((s, k) => s + Math.max(0, config[k]), 0);
if (weightSum <= 0) {
  WEIGHT_KEYS.forEach(k => (config[k] = DEFAULTS[k]));
  warnings.push('all score weights <= 0: defaults restored');
} else if (Math.abs(weightSum - 1) > 0.001) {
  WEIGHT_KEYS.forEach(k => (config[k] = Math.max(0, config[k]) / weightSum));
  warnings.push(`score weights summed to ${weightSum.toFixed(3)}: normalized to 1`);
}

// 4. Basic sanity checks
if (config.vph_log_ceil <= config.vph_log_floor) {
  config.vph_log_floor = DEFAULTS.vph_log_floor;
  config.vph_log_ceil = DEFAULTS.vph_log_ceil;
  warnings.push('vph_log_ceil <= vph_log_floor: defaults restored');
}
if (config.twitch_vph_log_ceil <= config.twitch_vph_log_floor) {
  config.twitch_vph_log_floor = DEFAULTS.twitch_vph_log_floor;
  config.twitch_vph_log_ceil = DEFAULTS.twitch_vph_log_ceil;
  warnings.push('twitch_vph_log_ceil <= twitch_vph_log_floor: defaults restored');
}
if (config.max_duration_s <= config.min_duration_s) {
  config.min_duration_s = DEFAULTS.min_duration_s;
  config.max_duration_s = DEFAULTS.max_duration_s;
  warnings.push('max_duration_s <= min_duration_s: defaults restored');
}
if (config.eligible_max_age_h > config.expire_age_h) {
  warnings.push('eligible_max_age_h > expire_age_h: candidates will expire before losing eligibility');
}
config.watchlist_items_per_source = Math.min(50, Math.max(1, Math.round(config.watchlist_items_per_source)));
config.charts_max_pages = Math.min(4, Math.max(0, Math.round(config.charts_max_pages)));
config.charts_enabled = config.charts_enabled ? 1 : 0;
config.twitch_clips_per_source = Math.min(100, Math.max(1, Math.round(config.twitch_clips_per_source)));
if (!config.twitch_client_id) warnings.push('twitch_client_id missing: Twitch source disabled');

// 5. Run context
const now = new Date();
const runId = `disc-${$now.toFormat('yyyyMMdd-HHmm')}-${$execution.id}`;

return [{
  json: {
    run_id: runId,
    workflow: '01 - US VIRAL | Discovery Engine',
    execution_mode: $execution.mode,
    started_at: now.toISOString(),
    started_at_ms: now.getTime(),
    config_rows: seen.size,
    config_warnings: warnings,
    config,
  },
}];

// Map Resolved IDs — pairs each channels.list response with its viral_sources row.
// Emits only sources that were resolved successfully (they get saved next).
// Failed handles are simply retried on the next run (1 quota unit each).

const sources = $('Needs Channel ID').all();
const out = [];

$input.all().forEach((item, i) => {
  const p = item.pairedItem;
  const idx = Array.isArray(p) ? p[0]?.item : p?.item;
  const src = sources[idx ?? i]?.json ?? {};
  const r = item.json ?? {};
  const ch = Array.isArray(r.items) ? r.items[0] : null;
  const uploads = ch?.contentDetails?.relatedPlaylists?.uploads;

  if (r.error || !ch || !uploads || src.id === undefined) return;

  out.push({
    json: {
      id: src.id,
      source_key: src.source_key,
      handle: src.handle,
      external_id: ch.id,
      uploads_playlist_id: uploads,
      channel_title: ch.snippet?.title ?? null,
      channel_country: ch.snippet?.country ?? null,
    },
    pairedItem: { item: i },
  });
});

return out;

// Build Watchlist Requests — one item per active YouTube source with a known uploads playlist.
// IDs resolved earlier in this same run (Resolve Channel IDs branch) are used immediately.

const cfg = $('Init Run').first().json.config;

const resolved = {};
try {
  if ($('Map Resolved IDs').isExecuted) {
    for (const it of $('Map Resolved IDs').all()) resolved[it.json.id] = it.json;
  }
} catch (e) {
  // branch not executed in this run: nothing to merge
}

const out = [];
for (const item of $input.all()) {
  const s = item.json ?? {};
  if (!s.source_key) continue; // empty watchlist placeholder
  const r = resolved[s.id];
  const playlist = s.uploads_playlist_id || r?.uploads_playlist_id;
  if (!playlist) continue; // handle not resolved yet: retried next run

  out.push({
    json: {
      source_row_id: s.id,
      source_key: s.source_key,
      name: s.name,
      channel_id: s.external_id || r?.external_id || null,
      uploads_playlist_id: playlist,
      category: s.category ?? null,
      pillar: s.pillar ?? null,
      priority: Number(s.priority ?? 3),
      learned_weight: Number(s.learned_weight ?? 1),
      baseline_vph: s.baseline_vph ?? null,
      rights_mode: s.rights_mode || 'discovery_only',
      max_results: cfg.watchlist_items_per_source,
    },
  });
}

return out;

// Build Video Batches — merges every video ID found in this run into batches of 50 for videos.list.
// Sources: watchlist uploads (only recent ones), tracked candidates (WATCHING/ELIGIBLE), YouTube charts.
// Chart videos already contain full details, so they are NOT refetched (saves quota).
// First item carries `meta` (videoId -> how it was discovered) used later by the scoring node.

const run = $('Init Run').first().json;
const cfg = run.config;
const nowMs = run.started_at_ms;
const maxAgeMs = cfg.expire_age_h * 3600 * 1000;

const meta = {};
const add = (id, via, sourceKey) => {
  if (!id) return;
  const m = (meta[id] ??= { via: [], source_key: null });
  if (!m.via.includes(via)) m.via.push(via);
  if (sourceKey && !m.source_key) m.source_key = sourceKey;
};
const pairIndex = (item, i) => {
  const p = item.pairedItem;
  const idx = Array.isArray(p) ? p[0]?.item : p?.item;
  return idx ?? i;
};

const stats = { uploads_seen: 0, uploads_recent: 0, tracked_refresh: 0, charts_items: 0 };

// 1. Watchlist uploads (keep only videos younger than expire_age_h)
const requests = $('Build Watchlist Requests').all();
$('YT Uploads').all().forEach((item, i) => {
  const src = requests[pairIndex(item, i)]?.json ?? {};
  for (const pi of item.json?.items ?? []) {
    stats.uploads_seen++;
    const id = pi.contentDetails?.videoId;
    const pub = Date.parse(pi.contentDetails?.videoPublishedAt ?? '');
    if (!id || !Number.isFinite(pub) || nowMs - pub > maxAgeMs) continue;
    stats.uploads_recent++;
    add(id, 'watchlist', src.source_key);
  }
});

// 2. Tracked YouTube candidates to refresh (Twitch ones are refreshed by the Twitch branch)
for (const item of $('Get Tracked Candidates').all()) {
  const r = item.json ?? {};
  if (!r.content_id || (r.platform ?? 'youtube') !== 'youtube' || !['WATCHING', 'ELIGIBLE'].includes(r.status)) continue;
  stats.tracked_refresh++;
  add(r.content_id, 'tracked', r.source_key);
}

// 3. Charts (details already available, not refetched)
const chartIds = new Set();
if (cfg.charts_enabled) {
  for (const page of $('YT Charts US').all()) {
    for (const v of page.json?.items ?? []) {
      if (!v?.id) continue;
      stats.charts_items++;
      chartIds.add(v.id);
      add(v.id, 'charts', null);
    }
  }
}

// 4. Batches of 50 IDs (videos.list limit)
const toFetch = Object.keys(meta).filter(id => !chartIds.has(id));
const batches = [];
for (let i = 0; i < toFetch.length; i += 50) batches.push(toFetch.slice(i, i + 50));
if (batches.length === 0) batches.push([]); // keep the chain alive: charts/tracked still need scoring

return batches.map((ids, i) => ({
  json: {
    batch_index: i,
    batch_count: batches.length,
    ids: ids.join(','),
    id_count: ids.length,
    ...(i === 0 ? { meta, stats: { ...stats, unique_ids: Object.keys(meta).length, to_fetch: toFetch.length } } : {}),
  },
}));

// Score & State — computes metrics, Trend Score and state transitions for every video/clip of this run
// (YouTube videos and Twitch clips are normalised to the same record first).
// Pure math, no AI. Output = one row per candidate to upsert into viral_candidates (+ _snapshot, _summary).
// Rules:
//  - Rows owned by other workflows (SELECTED, PROCESSING, READY, SCHEDULED, PUBLISHED, ...) are never touched.
//  - New videos failing hard filters are NOT stored (only counted). Tracked ones become REJECTED/EXPIRED.
//  - If a tracked video was checked less than min_velocity_interval_h ago, it is skipped (no fake velocity).

const run = $('Init Run').first().json;
const cfg = run.config;
const nowMs = run.started_at_ms;
const nowIso = run.started_at;
const batch0 = $('Build Video Batches').first().json;
const meta = batch0.meta ?? {};

const OWNED_BY_DISCOVERY = ['WATCHING', 'ELIGIBLE'];
const CATEGORY_PILLAR = { '20': 'gaming', '17': 'sports', '23': 'comedy', '24': 'entertainment', '22': 'people', '28': 'tech', '10': 'music', '1': 'film' };

// ---------- helpers ----------
const clamp = (x, lo = 0, hi = 1) => Math.min(hi, Math.max(lo, x));
const num = v => (v === undefined || v === null || v === '' || !Number.isFinite(Number(v)) ? null : Number(v));
const round = (x, d = 2) => (x === null || !Number.isFinite(x) ? null : Math.round(x * 10 ** d) / 10 ** d);
const isoDurationToSec = s => {
  const m = /^P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$/.exec(s ?? '');
  if (!m) return null;
  return (+m[1] || 0) * 86400 + (+m[2] || 0) * 3600 + (+m[3] || 0) * 60 + (+m[4] || 0);
};
const langOk = lang => {
  if (!lang) return true; // unknown language accepted
  const l = lang.toLowerCase();
  return cfg.allowed_languages.includes(l) || cfg.allowed_languages.includes(l.split('-')[0]);
};

// ---------- lookups ----------
const sources = {};
const sourceByChannel = {};
let twitchSources = [];
try { twitchSources = $('Get Twitch Sources').all(); } catch (e) { twitchSources = []; }
for (const it of [...$('Get Active Sources').all(), ...twitchSources]) {
  const s = it.json ?? {};
  if (!s.source_key) continue;
  sources[s.source_key] = s;
  if (s.external_id) sourceByChannel[s.external_id] = s;
}
const existing = {};
for (const it of $('Get Tracked Candidates').all()) {
  const r = it.json ?? {};
  if (r.candidate_key) existing[r.candidate_key] = r;
}

// ---------- collect + normalise items (YouTube videos, Twitch clips) ----------
const records = {};
const ytRecord = v => {
  const sn = v.snippet ?? {};
  const st = v.statistics ?? {};
  const thumbs = sn.thumbnails ?? {};
  return {
    platform: 'youtube',
    id: v.id,
    url: `https://www.youtube.com/watch?v=${v.id}`,
    title: sn.title ?? '',
    channelId: sn.channelId ?? null,
    channelTitle: sn.channelTitle ?? null,
    publishedAt: sn.publishedAt,
    views: num(st.viewCount) ?? 0,
    likes: num(st.likeCount),
    comments: num(st.commentCount),
    duration: isoDurationToSec(v.contentDetails?.duration),
    categoryId: sn.categoryId ?? null,
    lang: (sn.defaultAudioLanguage || sn.defaultLanguage || '').toLowerCase(),
    live: sn.liveBroadcastContent ?? 'none',
    license: v.status?.license ?? null,
    madeForKids: v.status?.madeForKids === true,
    thumbnail: (thumbs.maxres ?? thumbs.high ?? thumbs.medium ?? thumbs.default)?.url ?? null,
    metaSourceKey: meta[v.id]?.source_key ?? null,
    via: meta[v.id]?.via ?? [],
  };
};
for (const it of $('YT Video Details').all()) for (const v of it.json?.items ?? []) if (v?.id) records[`youtube:${v.id}`] = ytRecord(v);
if (cfg.charts_enabled) {
  for (const it of $('YT Charts US').all()) for (const v of it.json?.items ?? []) if (v?.id && !records[`youtube:${v.id}`]) records[`youtube:${v.id}`] = ytRecord(v);
}

const twitchSourceByBroadcaster = {};
let twitchRequests = [];
try { twitchRequests = $('Build Clip Requests').all().map(i => i.json ?? {}); } catch (e) { twitchRequests = []; }
for (const r of twitchRequests) if (r.broadcaster_id) twitchSourceByBroadcaster[r.broadcaster_id] = r.source_key;
let twitchItems = [];
try { twitchItems = $('Twitch Clips').all(); } catch (e) { twitchItems = []; }
for (const it of twitchItems) {
  for (const c of it.json?.data ?? []) {
    if (!c?.id) continue;
    records[`twitch:${c.id}`] = {
      platform: 'twitch',
      id: c.id,
      url: c.url,
      title: c.title ?? '',
      channelId: c.broadcaster_id ?? null,
      channelTitle: c.broadcaster_name ?? null,
      publishedAt: c.created_at,
      views: num(c.view_count) ?? 0,
      likes: null,
      comments: null,
      duration: num(c.duration),
      categoryId: null,
      lang: (c.language || '').toLowerCase(),
      live: 'none',
      license: 'twitch',
      madeForKids: false,
      thumbnail: c.thumbnail_url ?? null,
      metaSourceKey: twitchSourceByBroadcaster[c.broadcaster_id] ?? null,
      via: ['twitch_clips'],
    };
  }
}

const summary = {
  videos_evaluated: 0, new_candidates: 0, updated_candidates: 0, eligible: 0, expired: 0, rejected: 0,
  skipped_locked: 0, skipped_too_soon: 0, rejected_new: 0, reject_reasons: {},
};
const reject = reason => (summary.reject_reasons[reason] = (summary.reject_reasons[reason] || 0) + 1);

const rows = [];

for (const [key, rec] of Object.entries(records)) {
  summary.videos_evaluated++;
  const id = rec.id;
  const ex = existing[key];

  // 1. Never touch rows owned by Factory/Publisher
  if (ex && !OWNED_BY_DISCOVERY.includes(ex.status)) { summary.skipped_locked++; continue; }

  // 2. Parsed fields
  const pubMs = Date.parse(rec.publishedAt ?? '');
  const views = rec.views;
  const likes = rec.likes;
  const comments = rec.comments;
  const duration = rec.duration;
  const categoryId = rec.categoryId;
  const lang = rec.lang;
  const ageH = Math.max((nowMs - pubMs) / 3.6e6, 0.25);

  // 3. Source resolution: discovery meta -> existing row -> channel match -> charts
  const src =
    sources[rec.metaSourceKey] ?? sources[ex?.source_key] ?? sourceByChannel[rec.channelId] ?? null;
  const sourceKey = src?.source_key ?? rec.metaSourceKey ?? ex?.source_key ?? `${rec.platform}:chart_us`;
  const priority = num(src?.priority) ?? 2;
  const learnedWeight = num(src?.learned_weight) ?? 1;
  const baseline = num(src?.baseline_vph);

  // 4. Hard filters
  let hardFail = null;
  if (!Number.isFinite(pubMs)) hardFail = 'no_publish_date';
  else if (rec.live && rec.live !== 'none') hardFail = 'live_or_upcoming';
  else if (categoryId && cfg.charts_excluded_categories.includes(String(categoryId))) hardFail = `category_${categoryId}`;
  else if (!langOk(lang)) hardFail = 'language';
  else if ((cfg.title_exclude_keywords ?? []).some(k => rec.title.toLowerCase().includes(k))) hardFail = 'title_keyword';
  else if (rec.madeForKids) hardFail = 'made_for_kids';
  else if (duration === null || duration < (rec.platform === 'twitch' ? (cfg.twitch_min_duration_s ?? 5) : cfg.min_duration_s)) hardFail = 'too_short';
  else if (duration > cfg.max_duration_s) hardFail = 'too_long';
  // Twitch clips keep getting views for days: they get their own (longer) windows
  const isTwitch = rec.platform === 'twitch';
  const expireH = isTwitch ? cfg.twitch_expire_age_h : cfg.expire_age_h;
  const eligibleMaxH = isTwitch ? cfg.twitch_eligible_max_age_h : cfg.eligible_max_age_h;
  const tooOld = ageH > expireH;

  if (!ex && (hardFail || tooOld)) { summary.rejected_new++; reject(hardFail ?? 'too_old'); continue; }

  // 5. Velocity / acceleration
  let vphRecent, accel;
  const avgVph = views / ageH;
  if (ex) {
    const dtH = (nowMs - Date.parse(ex.last_checked_at)) / 3.6e6;
    if (!Number.isFinite(dtH) || dtH < cfg.min_velocity_interval_h) { summary.skipped_too_soon++; continue; }
    vphRecent = Math.max(0, views - (num(ex.views) ?? 0)) / dtH;
    accel = clamp(vphRecent / Math.max(num(ex.velocity_views_hour) ?? avgVph, 1), 0.05, 20);
  } else {
    vphRecent = avgVph; // first sighting fallback
    accel = 1;          // neutral
  }

  // 6. Engagement (likes can be hidden)
  let engagement = null;
  if (views > 0 && likes !== null) engagement = (likes + 2 * (comments ?? 0)) / views;
  else if (views > 0 && comments !== null) engagement = (3 * comments) / views;

  // 7. Components 0..1
  // Twitch clips get far fewer views than YouTube videos: each platform has its own velocity scale
  const vFloor = rec.platform === 'twitch' ? cfg.twitch_vph_log_floor : cfg.vph_log_floor;
  const vCeil = rec.platform === 'twitch' ? cfg.twitch_vph_log_ceil : cfg.vph_log_ceil;
  const V = clamp((Math.log10(Math.max(vphRecent, 1)) - vFloor) / (vCeil - vFloor));
  const O = baseline && baseline > 0 ? clamp((Math.log2(Math.max(vphRecent, 1) / baseline) + 1) / 4) : 0.5;
  const A = clamp((Math.log2(accel) + 1) / 2);
  const E = engagement === null ? 0.5 : clamp(engagement / cfg.engagement_cap);
  const R = Math.exp(-ageH / cfg.recency_tau_h);
  const P = clamp(((priority - 1) / 4) * learnedWeight);
  const score = round(100 * (cfg.w_velocity * V + cfg.w_outperformance * O + cfg.w_acceleration * A +
    cfg.w_engagement * E + cfg.w_recency * R + cfg.w_priority * P), 1);

  const snapshotCount = (num(ex?.snapshot_count) ?? 0) + 1;
  const confidence = snapshotCount >= 3 ? 'high' : snapshotCount === 2 ? 'med' : 'low';

  // 8. Rights (deterministic, from source rights_mode + YouTube license)
  const rightsMode = src?.rights_mode ?? 'discovery_only';
  const rightsStatus = ['permission', 'licensed', 'own'].includes(rightsMode) ? 'ALLOWED'
    : rec.license === 'creativeCommon' ? 'ALLOWED_CC' : 'DISCOVERY_ONLY';

  // 9. State machine
  let newStatus, reason;
  // ELIGIBLE = good score now, OR a confirmed peak above the bar while the score has not collapsed
  // (fast clips peak while still small: without this they drop out before reaching enough views).
  // Twitch also needs a minimum of views, so ELIGIBLE means "ready for the Factory".
  const peak = Math.max(score, num(ex?.peak_trend_score) ?? 0);
  const scoreNow = (confidence !== 'low' && score >= cfg.eligible_score_min) || score >= cfg.eligible_score_min_lowconf;
  const scoreKept = snapshotCount >= 2 && peak >= cfg.eligible_score_min && score >= cfg.eligible_keep_min;
  const viewsOk = !isTwitch || views >= cfg.twitch_eligible_min_views;
  if (tooOld) { newStatus = 'EXPIRED'; reason = `age ${Math.round(ageH)}h > ${expireH}h`; }
  else if (hardFail) { newStatus = 'REJECTED'; reason = hardFail; }
  else if (ageH > eligibleMaxH) { newStatus = 'WATCHING'; reason = `age ${Math.round(ageH)}h > eligible window`; }
  else if ((scoreNow || scoreKept) && viewsOk) {
    newStatus = 'ELIGIBLE'; reason = scoreNow ? `score ${score} (${confidence})` : `score ${score}, peak ${peak} (kept)`;
  } else if (scoreNow || scoreKept) {
    newStatus = 'WATCHING'; reason = `score ${score} but ${views} views < ${cfg.twitch_eligible_min_views}`;
  } else { newStatus = 'WATCHING'; reason = `score ${score} (${confidence})`; }

  const prevStatus = ex?.status ?? null;
  if (!ex) summary.new_candidates++; else summary.updated_candidates++;
  if (newStatus === 'ELIGIBLE') summary.eligible++;
  if (newStatus === 'EXPIRED') summary.expired++;
  if (newStatus === 'REJECTED') summary.rejected++;

  const via = [...new Set([...(ex?.discovered_via ? ex.discovered_via.split(',') : []), ...rec.via])].filter(Boolean);

  rows.push({
    json: {
      candidate_key: key,
      platform: rec.platform,
      content_id: id,
      source_key: sourceKey,
      discovered_via: via.join(',') || 'tracked',
      creator_id: rec.channelId,
      creator_name: rec.channelTitle,
      title: rec.title.slice(0, 300),
      url: rec.url,
      thumbnail_url: rec.thumbnail,
      category: src?.category ?? 'chart',
      yt_category_id: categoryId,
      pillar: src?.pillar ?? CATEGORY_PILLAR[categoryId] ?? 'other',
      language: lang || null,
      license: rec.license,
      published_at: new Date(pubMs).toISOString(),
      first_seen_at: ex?.first_seen_at ?? nowIso,
      last_checked_at: nowIso,
      duration_seconds: duration,
      views,
      likes,
      comments,
      avg_views_hour: round(avgVph, 1),
      velocity_views_hour: round(vphRecent, 1),
      accel_ratio: round(accel, 3),
      engagement_rate: round(engagement, 4),
      trend_score: score,
      peak_trend_score: peak,
      score_confidence: confidence,
      snapshot_count: snapshotCount,
      prev_views: ex ? num(ex.views) : null,
      prev_checked_at: ex?.last_checked_at ?? null,
      prev_velocity: ex ? num(ex.velocity_views_hour) : null,
      source_priority: priority,
      status: newStatus,
      status_reason: reason,
      status_changed_at: newStatus !== prevStatus ? nowIso : (ex?.status_changed_at ?? nowIso),
      rights_status: rightsStatus,
      processing_started_at: null,
      _components: { V: round(V, 3), O: round(O, 3), A: round(A, 3), E: round(E, 3), R: round(R, 3), P: round(P, 3) },
    },
  });
}

rows.sort((a, b) => b.json.trend_score - a.json.trend_score);

const runSummary = { ...summary, ...(batch0.stats ?? {}) };
if (rows.length === 0) return [{ json: { _empty: true, _summary: runSummary } }];
rows[0].json._summary = runSummary;
return rows;

// Build Run Log — one row for viral_runs: counts, estimated quota and HTTP errors of this run.

const run = $('Init Run').first().json;
const s = $('Score & State').first().json._summary ?? {};

const safeAll = name => { try { return $(name).isExecuted ? $(name).all() : []; } catch (e) { return []; } };
const youtubeNodes = ['YT Resolve Handle', 'YT Uploads', 'YT Charts US', 'YT Video Details'];
const httpNodes = [...youtubeNodes, 'Twitch Users', 'Twitch Clips'];
const errors = [];
let quota = 0;
for (const n of httpNodes) {
  const items = safeAll(n);
  if (youtubeNodes.includes(n)) quota += items.length; // YouTube quota: 1 unit per request (page/batch)
  for (const it of items) if (it.json?.error) errors.push(`${n}: ${String(it.json.error.message ?? it.json.error).slice(0, 150)}`);
}

const notes = {
  errors,
  config_warnings: run.config_warnings ?? [],
  reject_reasons: s.reject_reasons ?? {},
  rejected_new: s.rejected_new ?? 0,
  skipped_too_soon: s.skipped_too_soon ?? 0,
  skipped_locked: s.skipped_locked ?? 0,
};

return [{
  json: {
    run_id: run.run_id,
    workflow: run.workflow,
    started_at: run.started_at,
    finished_at: new Date().toISOString(),
    status: errors.length ? 'PARTIAL' : 'SUCCESS',
    sources_polled: safeAll('Build Watchlist Requests').length,
    videos_fetched: s.videos_evaluated ?? 0,
    new_candidates: s.new_candidates ?? 0,
    updated_candidates: s.updated_candidates ?? 0,
    eligible: s.eligible ?? 0,
    expired: s.expired ?? 0,
    rejected: s.rejected ?? 0,
    quota_units_est: quota,
    errors: JSON.stringify(notes).slice(0, 4000),
  },
}];

// Build Clip Requests — one Twitch API request per streamer (clips of the last N hours, most viewed first)
// + refresh requests for Twitch candidates already tracked (WATCHING/ELIGIBLE), up to 100 ids per call.
// Always returns at least one item so the chain reaches Score & State.

const run = $('Init Run').first().json;
const cfg = run.config;

const users = {};
try {
  for (const it of $('Twitch Users').all()) for (const u of it.json?.data ?? []) users[u.login.toLowerCase()] = u;
} catch (e) {
  // Twitch Users did not run
}

const since = new Date(run.started_at_ms - cfg.twitch_clip_window_h * 3600 * 1000).toISOString();
const out = [];
const unresolved = [];

for (const it of $('Get Twitch Sources').all()) {
  const s = it.json ?? {};
  if (!s.source_key) continue;
  const login = String(s.handle ?? '').replace('@', '').trim().toLowerCase();
  const u = users[login];
  if (!u) { unresolved.push(login); continue; }
  out.push({
    json: {
      kind: 'broadcaster',
      source_key: s.source_key,
      login,
      broadcaster_id: u.id,
      url: `https://api.twitch.tv/helix/clips?broadcaster_id=${u.id}&started_at=${encodeURIComponent(since)}&first=${cfg.twitch_clips_per_source}`,
    },
  });
}

const tracked = $('Get Tracked Candidates').all().map(i => i.json ?? {})
  .filter(r => r.platform === 'twitch' && r.content_id && ['WATCHING', 'ELIGIBLE'].includes(r.status));
for (let i = 0; i < tracked.length; i += 100) {
  const ids = tracked.slice(i, i + 100).map(r => 'id=' + encodeURIComponent(r.content_id)).join('&');
  out.push({ json: { kind: 'refresh', url: `https://api.twitch.tv/helix/clips?${ids}` } });
}

if (out.length === 0) out.push({ json: { kind: 'none', url: 'https://api.twitch.tv/helix/clips?id=none' } });
out[0].json.unresolved_logins = unresolved;
return out;
